begin;

-- George Brown College (Toronto, Canada): new university record.
--
-- Sources: George Brown's own 2025-26 International Student Viewbook (166 programs with
-- codes, lengths, fees and intake months), its International Tuition Fees and Related Costs
-- page, and its International Students Awards and Scholarships page. The live site is behind
-- edge protection that blocks automated access, so pages were read from Internet Archive
-- snapshots; the viewbook PDF is George Brown's own published document.
--
-- Fee basis: the per-program amounts are George Brown's published estimates covering tuition,
-- materials, student service and ancillary fees for the FIRST TWO SEMESTERS, not pure annual
-- tuition. The viewbook states these are based on programs starting in Fall 2024, so they are
-- indicative rather than current 2026-27 pricing. Application fee (CAD 110) is from the
-- 2025-2026 international fee schedule.
--
-- Left null deliberately (not published by George Brown, not guessed): ranking,
-- acceptance_rate, graduate_employability, and per-program campus.
--
-- is_published is FALSE: the record has no logo or cover image yet. Upload both from the admin
-- dashboard, then set is_published = true.

insert into public.universities (id, name, slug, short_description, overview, city, founded_year, ranking, total_students, number_of_campuses, acceptance_rate, graduate_employability, international_students, intake_months, tuition_fee_min, tuition_fee_max, tuition_currency, has_on_campus, has_online, has_hybrid, is_featured, is_published, country_id, created_at, updated_at)
values (gen_random_uuid(), 'George Brown College', 'george-brown-college', 'George Brown College is a large public college in downtown Toronto offering more than 160 career-focused certificate, diploma, degree and graduate certificate programs to international students, with three campuses, strong employer connections and three intakes a year.', 'George Brown College is a publicly funded Ontario college founded in 1967 and based in downtown Toronto, where it teaches more than 27,000 full-time students across three campuses: Casa Loma, St. James and Waterfront. International students make up roughly 29 per cent of full-time enrolment, drawn by the college''s location in Canada''s largest city and its focus on applied, employment-ready training.

The college offers over 160 programs to international students across seven academic centres: Arts, Design and Information Technology; Business; Community Services and Early Childhood; Construction and Engineering Technologies; Health Sciences; Hospitality and Culinary Arts; and Preparatory and Liberal Studies. Credentials range from one-year Ontario College Certificates through two and three-year diplomas and advanced diplomas, four-year honours bachelor degrees, and one-year graduate certificates designed for students who already hold a diploma or degree. Most programs include work-integrated learning, and many carry a co-op or field placement term.

Students who need to strengthen their English before starting a post-secondary program can enter through the college''s English for Academic Purposes (EAP) pathway, which is billed per eight-week session; graduates of EAP level 8 are exempt from the English admission test for most George Brown programs. In October 2025 the institution rebranded as George Brown Polytechnic, though its legal name remains the George Brown College of Applied Arts and Technology.', 'Toronto, ON', 1967, null, 27128, 3, null, null, 29, 'September, January, May', 18045, 39050, 'CAD', true, true, false, false, false, (select id from public.countries where slug = 'canada'), now(), now());

-- 166 programs from the international viewbook. entry_requirements, application_fee and campus
-- are identical for every program, so they are set once in the SELECT rather than repeated 166 times.
insert into public.programs (id, university_id, name, slug, degree_level, field, campus, application_fee,
  tuition_fee_per_year, duration_years, intake_months, entry_requirements, learn_more_url, description,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.slug, v.degree_level::"DegreeType", v.field, null,
  'CAD 110', v.tuition, v.duration, v.intake,
  'Ontario Secondary School Diploma or equivalent for post-secondary entry; graduate certificate programs require a completed diploma or degree. Proof of English proficiency is required and George Brown accepts IELTS Academic, TOEFL iBT, PTE and Duolingo, with test results valid for two years. Minimum scores and any subject prerequisites are set per program, so applicants should confirm the requirement for their specific program code. Applicants who do not yet meet the English requirement can enter through George Brown''s English for Academic Purposes (EAP) pathway.',
  v.learn_more_url, v.description, now(), now()
from (select id from public.universities where slug = 'george-brown-college') as uni,
