  ('Human Services Foundations', 'human-services-foundations-a113', 'CERTIFICATE', 'Preparatory & Liberal Studies', 'CAD 18,550', 1, 'September, January', 'https://www.georgebrown.ca/A113', 'Ontario College Certificate from George Brown College''s Centre for Preparatory & Liberal Studies, program code A113. Program length 1 year. Intakes: September, January. Estimated cost for international students is CAD 18,550, covering tuition, materials, student service and ancillary fees for the first two semesters.'),
  ('General Arts and Science – One-Year', 'general-arts-and-science-one-year-r104', 'CERTIFICATE', 'Preparatory & Liberal Studies', 'CAD 18,600', 1, 'September, January', 'https://www.georgebrown.ca/R104', 'Ontario College Certificate from George Brown College''s Centre for Preparatory & Liberal Studies, program code R104. Program length 1 year. Intakes: September, January. Estimated cost for international students is CAD 18,600, covering tuition, materials, student service and ancillary fees for the first two semesters.'),
  ('General Arts & Science – English for Academic Purposes (EAP)', 'general-arts-and-science-english-for-academic-purposes-eap-r115', 'CERTIFICATE', 'Preparatory & Liberal Studies', 'CAD 3,430 per 8-week session', 1.5, 'January, March, May, July, September, October', 'https://www.georgebrown.ca/R115', 'Ontario College Certificate from George Brown College''s Centre for Preparatory & Liberal Studies, program code R115. Delivered over three semesters covering EAP levels 1 to 9, with placement by English test score. Intakes: January, March, May, July, September, October. Tuition is billed per 8-week session rather than per year. Graduates of EAP level 8 are exempt from the English admission test for most George Brown post-secondary programs.'),
  ('General Arts & Science', 'general-arts-and-science-r101', 'DIPLOMA', 'Preparatory & Liberal Studies', 'CAD 18,575', 2, 'September, January', 'https://www.georgebrown.ca/R101', 'Ontario College Diploma from George Brown College''s Centre for Preparatory & Liberal Studies, program code R101. Program length 2 years. Intakes: September, January. Estimated cost for international students is CAD 18,575, covering tuition, materials, student service and ancillary fees for the first two semesters.')
) as v(name, slug, degree_level, field, tuition, duration, intake, learn_more_url, description);

-- International scholarships and awards.
insert into public.scholarships (id, university_id, name, type, description, value, learn_more_url,
  created_at, updated_at)
select gen_random_uuid(), uni.id, v.name, v.type::"ScholarshipType", v.description, v.value,
  'https://www.georgebrown.ca/apply/financial-aid/awards-and-scholarships/types-of-awards/international', now(), now()
from (select id from public.universities where slug = 'george-brown-college') as uni,
(values
  ('Scotiabank International Partner Entrance Scholarship', 'MERIT_BASED', 'Two scholarships of CAD 5,000 are awarded each academic year to newly admitted international students in the first year of a full-time diploma, degree or graduate certificate program. Students from George Brown''s partner institutions in the Caribbean, China, Central and South America and India are particularly encouraged to apply. Requires a valid Canadian study permit, a cumulative GPA of 3.0 and demonstrated leadership.', 'CAD 5,000'),
  ('Scotiabank Bursaries', 'PARTIAL', 'Scotiabank funds 100 bursaries of CAD 1,000 each, totalling CAD 100,000, for international students. Applicants must be registered in a full-time program and demonstrate financial need.', 'CAD 1,000'),
  ('Woori Education Scholarship', 'MERIT_BASED', 'Awarded to an international student holding a valid study permit who is registered in a full-time diploma or degree program, based on academic performance and community contribution. Requires a minimum cumulative GPA of 3.3 across at least two consecutive full semesters.', null),
  ('International Student Leadership Award', 'MERIT_BASED', 'Available to any international student graduating from their program. Requires a minimum GPA of 3.5 and active involvement in the college or wider community.', null),
  ('Post-Secondary Scholarship for International Students: Diploma and Degree', 'MERIT_BASED', 'For international students in the second, third or fourth year of a diploma or degree program undertaking an approved international work or study experience. Requires a minimum GPA of 3.5 and community involvement.', null),
  ('Post-Secondary Scholarship for International Students: Certificate', 'MERIT_BASED', 'For international students in a certificate or graduate certificate program in any year of study. Requires a minimum GPA of 3.5 and active community involvement.', null),
  ('Assist on Scholarship for International Students in Two-year Programs', 'MERIT_BASED', 'Funded by Assist on Global Service in Canada Ltd. and open to registered international students in any year of study on two-year programs. Requires a minimum GPA of 3.0 and active involvement in the college or wider community.', null),
  ('Kimokran (Toronto) Scholarship for International Students', 'MERIT_BASED', 'Funded by Kimokran 16 Toronto Inc. for registered international students in their second year of study or higher. Requires a minimum GPA of 3.0 and active involvement in the college or wider community.', null),
  ('International Student Scholarship', 'PARTIAL', 'Open to full-time international students in any program who demonstrate financial need and have overcome obstacles in their studies. Requires a minimum GPA of 2.5.', null),
  ('International Centre Student Bursary', 'PARTIAL', 'Available to registered international students in any year of study across all programs who can demonstrate financial need and active involvement in the college or wider community.', null),
  ('International Student ESL Scholarship', 'MERIT_BASED', 'Awarded to an international student enrolled in the third module of the ESL programme who is actively involved in the college or wider community.', null)
) as v(name, type, description, value);

-- Admission steps.
insert into public.admission_steps (id, university_id, step_number, title, description, created_at, updated_at)
select gen_random_uuid(), uni.id, v.step_number, v.title, v.description, now(), now()
from (select id from public.universities where slug = 'george-brown-college') as uni,
(values
  (1, 'Choose Your Program and Apply Online', 'Apply directly to George Brown through its online application, selecting your program by its code. There is a non-refundable application fee of CAD 110. Most programs start in September, January or May, though intake months vary by program, and popular programs fill well before the term begins.'),
  (2, 'Submit Transcripts and Proof of English', 'Provide academic transcripts from your home country for credential assessment, along with proof of English proficiency. George Brown accepts IELTS Academic, TOEFL iBT, PTE and Duolingo, with results valid for two years. Applicants who do not yet meet the English requirement can begin in the English for Academic Purposes (EAP) pathway instead.'),
  (3, 'Receive Your Offer and Pay the Deposit', 'If your application is successful the International Centre issues an offer of admission. Accept the offer and pay the required tuition deposit to receive the Letter of Acceptance needed for your study permit application.'),
  (4, 'Apply for Your Canadian Study Permit', 'Use your Letter of Acceptance to apply to Immigration, Refugees and Citizenship Canada (IRCC) for a study permit. Apply as early as possible, since processing times vary by country and Ontario college applicants may also need a Provincial Attestation Letter.')
) as v(step_number, title, description);

commit;
